s='"""Local credential-free release checks; no hosted endpoints or build requests."""\nfrom pathlib import Path\nimport json\nimport os\nimport subprocess\n\nROOT = Path(__file__).resolve().parents[4]\nOUT = Path(\'docs/audit/p0-critical-remediation-20261111_131014/evidence\').resolve()\nenv = {"PATH": os.environ["PATH"], "TZ": "UTC", "EXPO_OFFLINE": "1",\n       "EXPO_NO_TELEMETRY": "1", "CI": "1"}\ncommands=[]\nmobile=\'mv004-recovery mv008-ownership notes-entitlement payment-success-owner payment-poll payment-request payment-verdict payment-routing checkout-security purchases notes-unlock release-payments-disabled notes-billing-choice\'.split()\nbackend=\'mv004-recovery mv005-create-order mv006-restoration settle-timestamp recovery razorpay-security razorpay-routing notes-choice-order billing-recovery-worker compensation-worker play-verification play-consumption play-reconcile-fairness play-order play-payment-worker phase-c-gates b-to-c-reporting b-to-c-worker p0-reversal p0-notification play-body\'.split()\nfor folder,names in [(\'mobile-app/scripts\',mobile),(\'supabase/tests\',backend)]:\n for n in names:\n  f=ROOT/folder/(n+\'-selftest.cjs\')\n  if f.exists():commands.append(([\'node\',str(f.relative_to(ROOT))],ROOT))\ncommands += [([\'node\',\'supabase/tests/google-reporting-selftest.cjs\',\'--production-only\'],ROOT),([\'node\',\'mobile-app/node_modules/typescript/bin/tsc\',\'--noEmit\',\'-p\',\'mobile-app/tsconfig.json\'],ROOT),([\'git\',\'diff\',\'--check\'],ROOT)]\nresults = []\nfor i, (cmd, cwd) in enumerate(commands):\n    try:\n        p = subprocess.run(cmd, cwd=cwd, env=env, capture_output=True, text=True, timeout=120)\n        code, output = p.returncode, p.stdout + p.stderr\n    except subprocess.TimeoutExpired:\n        code, output = 124, "Timed out after 120 seconds\\n"\n    name = f"p0-final-check-{i:02d}.log"\n    (OUT / name).write_text(output)\n    results.append({"command": cmd, "cwd": str(cwd.relative_to(ROOT)), "exit_code": code, "log": name})\n    print("PASS" if code == 0 else "FAIL", " ".join(cmd), flush=True)\n    (OUT / "p0-final-check-results.json").write_text(json.dumps(results, indent=2) + "\\n")\nraise SystemExit(any(r["exit_code"] for r in results))\n'
